package org.xingmu.tv;
import android.app.Activity;import android.os.Bundle;import android.content.Intent;import android.view.*;import android.widget.*;import java.util.*;
public final class LibraryActivity extends Activity {
 private List<CatalogItem> all=new ArrayList<>(),shown=new ArrayList<>();private String section;private LinearLayout list;private TextView count;
 @Override public void onCreate(Bundle b){super.onCreate(b);section=getIntent().getStringExtra("section");if(!Arrays.asList("films","domestic","foreign","opera").contains(section)){finish();return;}LinearLayout root=TvUi.root(this),head=TvUi.row(this);String title=section.equals("opera")?"戏曲频道":section.equals("films")?"网络影视":section.equals("foreign")?"国外电视直播":"国内电视直播";head.addView(TvUi.text(this,title,28,TvUi.INK),new LinearLayout.LayoutParams(0,-2,1));Button back=TvUi.button(this,"返回首页");back.setOnClickListener(v->finish());head.addView(back);root.addView(head);TvUi.gap(this,root,16);
 try{for(CatalogItem item:new CatalogRepository(this).load())if(section.equals("opera")?item.opera():item.section.equals(section))all.add(item);}catch(Exception e){TvUi.toast(this,"读取内容失败："+e.getMessage());}
 LinkedHashSet<String> groups=new LinkedHashSet<>();groups.add("全部");for(CatalogItem i:all)groups.add(section.equals("foreign")?i.country:i.category);List<String> options=new ArrayList<>(groups);LinearLayout filter=TvUi.row(this);filter.addView(TvUi.text(this,section.equals("foreign")?"国家  ":"分类  ",18,TvUi.MUTED));Spinner choice=new Spinner(this);ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,options);choice.setAdapter(adapter);filter.addView(choice,new LinearLayout.LayoutParams(TvUi.dp(this,240),TvUi.dp(this,48)));count=TvUi.text(this,"",16,TvUi.MUTED);filter.addView(count);root.addView(filter);TvUi.gap(this,root,12);
 ScrollView scroll=new ScrollView(this);list=TvUi.col(this);scroll.addView(list);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));choice.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int pos,long id){render(options.get(pos));}});render("全部");
 }
 private void render(String group){shown.clear();for(CatalogItem i:all)if(group.equals("全部")||group.equals(section.equals("foreign")?i.country:i.category))shown.add(i);count.setText("   "+shown.size()+" 项");list.removeAllViews();if(shown.isEmpty()){list.addView(TvUi.text(this,section.equals("opera")?"暂无纯戏曲授权内容。请导入戏曲点播或 operaOnly: true 的纯戏曲直播；混播台不自动纳入。":"暂无内容，可在设置中导入已授权目录",20,TvUi.MUTED));return;}
 for(int n=0;n<shown.size();n++){CatalogItem i=shown.get(n);final int index=n;Button card=TvUi.button(this,i.title+"\n"+(i.mode.equals("official")?"官方观看入口":i.category+" · 授权视频")+" · "+i.source);card.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);card.setTextSize(18);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,TvUi.dp(this,86));p.bottomMargin=TvUi.dp(this,10);list.addView(card,p);card.setOnClickListener(v->{ArrayList<String> ids=new ArrayList<>();for(CatalogItem item:shown)ids.add(item.id);startActivity(new Intent(this,PlayerActivity.class).putStringArrayListExtra("ids",ids).putExtra("index",index));});}
 }
}
